BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT119-S2-Q15$batch09$ AND q.stimulus=$batch09$One’s palate is to a great extent socially determined: that is, if we notice that a lot of people enjoy consuming a certain type of food, we will eventually come to like the food as well, once we have become accustomed to the food.$batch09$ AND q.prompt=$batch09$Which one of the following most closely conforms to the principle above?$batch09$ AND q.correct_choice=$batch09$C$batch09$) THEN RAISE EXCEPTION 'Question changed: PT119-S2-Q15'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch09$26a9e931-67ea-48fe-8bea-82d123b58b11$batch09$) <> 2 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch09$26a9e931-67ea-48fe-8bea-82d123b58b11$batch09$) <> 4 THEN RAISE EXCEPTION 'Explanation changed: PT119-S2-Q15'; END IF; END $guard$;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$E$batch09$, $batch09$This is the trap, picked by 8%. Sally's family uses jalapeños often, so #1 roughly fits, and Sally has gotten used to them, so #2 fits. But #3 needs Sally to come to like them. All we're told is that Sally can now eat them without discomfort. Tolerating a food isn't liking it. C ends with George "very fond" of pierogis, so it hits all three beats.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT119-S2-Q15$batch09$ AND e.id=$batch09$26a9e931-67ea-48fe-8bea-82d123b58b11$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
